+export interface Discount {
+  code: string;
+  percent: number;
+}
+
+// TODO: load codes from the database
+const CODES: Discount[] = [
+  { code: 'WELCOME10', percent: 10 },
+  { code: 'VIP25', percent: 25 },
+];
+
+export function findDiscount(code: string): Discount | undefined {
+  return CODES.find((d) => d.code === code.toUpperCase());
+}
+
+export function applyDiscount(total: number, code: string): number {
+  const discount = findDiscount(code);
+  console.log('applying discount', discount);
+  if (!discount) return total;
+  return Math.round(total * (100 - discount.percent)) / 100;
+}
+
+export const MAX_PERCENT = 50;
+export const MIN_TOTAL = 0;

